mapper.select:
SELECT COALESCE(MAX(FILE_SN), 0) + 1
FROM BOARD_FILE
WHERE BOARD_ID = #{boardId}

mapper.insert:
INSERT INTO BOARD_FILE (
    FILE_ID, BOARD_ID, FILE_SN, ORG_FILE_NM, SAVE_FILE_NM, FILE_PATH, FILE_SIZE, CONTENT_TYPE
) VALUES (
    #{fileId}, #{boardId}, #{fileSn}, #{orgFileNm}, #{saveFileNm}, #{filePath}, #{fileSize}, #{contentType}
)
